tl;dr使用 all标题来解决问题。
related issue: go@issue43854
//go:embed public
var fs embed.FS



过程今天在尝试用go embed来提供前端文件的时候遇到了一个问题，有些文件就是加载不出来。

我用了这个函数尝试获取所有文件，看看到底是哪里出了问题
func getAllFilenames(fs *embed.FS, dir string) (out []string, err error) &#123;
	if len(dir) == 0 &#123;
		dir = "."
	&#125;

	entries, err := fs.ReadDir(dir)
	if err != nil &#123;
		return nil, err
	&#125;

	for _, entry := range entries &#123;
		fp := path.Join(dir, entry.Name())
		if entry.IsDir() &#123;
			res, err := getAllFilenames(fs, fp)
			if err != nil &#123;
				return nil, err
			&#125;

			out = append(out, res...)

			continue
		&#125;

		out = append(out, fp)
	&#125;

	return
&#125;

from source

我得到了如下输出
[public&#x2F;200.html public&#x2F;404.html public&#x2F;admin&#x2F;credential&#x2F;index.html public&#x2F;admin&#x2F;login&#x2F;index.html public&#x2F;admin&#x2F;panel&#x2F;index.html public&#x2F;favicon.ico public&#x2F;index.html public&#x2F;search&#x2F;answer&#x2F;index.html public&#x2F;search&#x2F;article&#x2F;index.html] &lt;nil&gt;

发现任何在_nuxt文件夹下的文件都不在里面。于是我猜测go embed默认不会包含开头为_的文件或者文件夹
经过搜索，果然发现了解决方案。
https://github.com/golang/go/issues/43854
使用all即可
//go:embed all:pattern



Gin Gingle Page Applicationsolution
type GinSPA struct &#123;
	sgin.CommonApp
	fsEmbed fs.ReadFileFS
&#125;

func NewGinSPA(fsEmbed *embed.FS, fsPrefix string) *GinSPA &#123;
	fsys, err :&#x3D; fs.Sub(fsEmbed, fsPrefix)
	if err !&#x3D; nil &#123;
		panic(err)
	&#125;
	return &amp;GinSPA&#123;
		fsEmbed: fsys.(fs.ReadFileFS),
	&#125;
&#125;

func (g *GinSPA) Create(engine *gin.Engine, router gin.IRouter) error &#123;
	engine.NoRoute(g.handleSpa)
	return nil
&#125;


func (g *GinSPA) handleSpa(c *gin.Context) &#123;
	path :&#x3D; c.Request.URL.Path
	if len(path) &gt; 0 &#123;
		path &#x3D; path[1:]
	&#125;
	if data, err :&#x3D; g.fsEmbed.ReadFile(path); err &#x3D;&#x3D; nil &#123;
		c.Data(200, mime.TypeByExtension(filepath.Ext(path)), data)
		return
	&#125;
	if data, err :&#x3D; g.fsEmbed.ReadFile(&quot;index.html&quot;); err !&#x3D; nil &#123;
		c.String(404, &quot;404 Not Found&quot;)
	&#125; else &#123;
		c.Data(200, mime.TypeByExtension(&quot;.html&quot;), data)
	&#125;
&#125;

本文仅为翻译，原文链接-&gt;Custom JSON Marshalling in Go


Go自带一个包encoding/json，这个包使序列化结构体(struct)和反序列化json变得异常简单。
例子
package main

import (
	"encoding/json"
	"os"
	"time"
)

type MyUser struct &#123;
	ID       int64     `json:"id"`
	Name     string    `json:"name"`
	LastSeen time.Time `json:"lastSeen"`
&#125;

func main() &#123;
	_ = json.NewEncoder(os.Stdout).Encode(
		&amp;MyUser&#123;1, "Ken", time.Now()&#125;,
	)
&#125;
输出
&#123;"id":1,"name":"Ken","lastSeen":"2009-11-10T23:00:00Z"&#125;

但是，如果我想改变序列化之后其中一个field的值应该怎么做呢？比如，我们想要把LastSeen修改为Unix时间戳的形式。
一个简单的方法就是使用一个辅助的结构体并在调用MarshalJSON方法的时候在辅助结构体内填上正确的格式。
func (u *MyUser) MarshalJSON() ([]byte, error) &#123;
	return json.Marshal(&amp;struct &#123;
		ID       int64  `json:"id"`
		Name     string `json:"name"`
		LastSeen int64  `json:"lastSeen"`
	&#125;&#123;
		ID:       u.ID,
		Name:     u.Name,
		LastSeen: u.LastSeen.Unix(),
	&#125;)
&#125;

这种方法当时使可以的，但是如果一个结构体有很多个字段field，那么这种方法就比较麻烦了（笨重.jpg）。最好可以直接把原来的结构体放进辅助结构体里，让辅助结构体继承所有不要被改变的field，只添加需要被改变的field。
func (u *MyUser) MarshalJSON() ([]byte, error) &#123;
	return json.Marshal(&amp;struct &#123;
		LastSeen int64 `json:"lastSeen"`
		*MyUser
	&#125;&#123;
		LastSeen: u.LastSeen.Unix(),
		MyUser:   u,
	&#125;)
&#125;

但是问题是，这个辅助的结构体同样会继承MarshalJSON这个方法，这样就会导致无限循环(其实就是MarshalJSON调用MarshalJSON)。
解决方法就是给原始的结构体做一个别名，这个别名会继承原始结构体的所有field但不会继承方法。
func (u *MyUser) MarshalJSON() ([]byte, error) &#123;
	type Alias MyUser
	return json.Marshal(&amp;struct &#123;
		LastSeen int64 `json:"lastSeen"`
		*Alias
	&#125;&#123;
		LastSeen: u.LastSeen.Unix(),
		Alias:    (*Alias)(u),
	&#125;)
&#125;

同样的方法可以用到UnmarshalJSON中
func (u *MyUser) UnmarshalJSON(data []byte) error &#123;
	type Alias MyUser
	aux := &amp;struct &#123;
		LastSeen int64 `json:"lastSeen"`
		*Alias
	&#125;&#123;
		Alias: (*Alias)(u),
	&#125;
	if err := json.Unmarshal(data, &amp;aux); err != nil &#123;
		return err
	&#125;
	u.LastSeen = time.Unix(aux.LastSeen, 0)
	return nil
&#125;

