    &quot;fyne.io&#x2F;fyne&#x2F;v2&#x2F;theme&quot;
    &quot;github.com&#x2F;aynakeya&#x2F;go-mpv&quot;
)

type WindowHandleMagic interface &#123;
    Wid() uintptr
&#125;

&#x2F;&#x2F; need to apply patch first
func GetWindowHandle(window fyne.Window) uintptr &#123;
    x, ok :&#x3D; window.(WindowHandleMagic)
    if ok &#123;
        return x.Wid()
    &#125;
    return 0
