func main() &#123;
    a :&#x3D; app.NewWithID(&quot;io.fyne.mpvdemo&quot;)
    a.SetIcon(theme.FyneLogo())
    window :&#x3D; a.NewWindow(&quot;Fyne MPV Player Demo&quot;)
