after open the link. the webpage return a very long base64 string.
decode base64 string will get a string which encrypted with zero-width stego.
data = ""

note that every 8 unicode character is separate by &quot;\u200d&quot; 
so separate characters by &quot;\u200d&quot; and replace &quot;\u200c&quot; with 0 and &quot;\u200b&quot; with 1. we get the flag

data = ""
data1 = base64.b64decode(data)
a = data1.decode()
# remove standard unicode character
for s in a:
    if ord(s) > 128:
        uns.append(s)
unss = "".join(uns)
uns1 = unss.split("\u200d")
print(len(uns1),uns1,unss.count("\u200d"))
def replacer(s:str):
    return s.replace("\u200c","0").replace("\u200b", "1")
for s in uns1:
    sss = replacer(s)
    print(chr(int(sss,2)),end="")

# TMCTF&#123;Jav@WebAppSpl0itzCh4inZ&#125;

0x1 tl;drgotm, a web question in linectf 2022. This is a very good example of golang server side template injection (ssti)
0x2 Vulnerabilitytake a brief a look at the code. In order to get the flag. we need to visit /flag whici is handled by flag_handler. 
flag_handler require a jwt token with IsAdmin=True. Therefore, in order to forge that, we need to have the secret of jwt token.


func flag_handler(w http.ResponseWriter, r *http.Request) &#123;
    token :&#x3D; r.Header.Get(&quot;X-Token&quot;)
    if token !&#x3D; &quot;&quot; &#123;
        id, is_admin :&#x3D; jwt_decode(token)
        if is_admin &#x3D;&#x3D; true &#123;
            &#x2F;&#x2F; write flag
            return
        &#125; else &#123;
            w.WriteHeader(http.StatusForbidden)
            return
        &#125;
    &#125;
&#125;

Then, the problem become how to get the jwt token from the server. 
In order to get the jwt secret, we need to use a ssti vulnerable in the root_handler. 
root_handler first obtain a Account struct from the token and print out the user id using template rendering. 
Since we can control the value in acc.id by register an account. We can inject arbitrary code into the template.
type Account struct &#123;
    id         string
    pw         string
    is_admin   bool
    secret_key string
&#125;
...
func root_handler(w http.ResponseWriter, r *http.Request) &#123;
    ...
    acc :&#x3D; get_account(id)
    ...
    tpl, err :&#x3D; template.New(&quot;&quot;).Parse(&quot;Logged in as &quot; + acc.id)
    ...
    return
&#125;


0x3 Some useful go ssti injection
&#123;&#123;.&#125;&#125; will print out the whole struct that being passed
&#123;&#123;.PublicField&#125;&#125;  will print out the public field
&#123;&#123;printf "%s" "asdf"&#125;&#125; will do a normal printf thing

package main

import (
    &quot;os&quot;
    &quot;text&#x2F;template&quot;
)

type SSTI struct &#123;
    privateMember         string
    PublicMember         string
    value   int
&#125;

func main() &#123;
    ssti :&#x3D; SSTI&#123;
        privateMember : &quot;private&quot;,
        PublicMember : &quot;public&quot;,
        value : 1,
    &#125;
    tpl, _ :&#x3D; template.New(&quot;&quot;).Parse(&quot;Here is &#123;&#123;.&#125;&#125; \n&quot;)
    tpl.Execute(os.Stdout, ssti) &#x2F;&#x2F; print &quot;Here is &#123;private public 1&#125;&quot;
    tpl, _ &#x3D; template.New(&quot;&quot;).Parse(&quot;Here is &#123;&#123;.PublicMember&#125;&#125; \n&quot;)
    tpl.Execute(os.Stdout, ssti) &#x2F;&#x2F; print &quot;Here is public&quot;
    tpl, _ &#x3D; template.New(&quot;&quot;).Parse(&quot;Here is &#123;&#123;printf \&quot;%s\&quot; \&quot;asdf\&quot;&#125;&#125; \n&quot;)
    tpl.Execute(os.Stdout, ssti) &#x2F;&#x2F; print &quot;Here is asdf&quot;&quot;
&#125;


